"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans


def clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def gap_label(span: Span) -> str:
    start, end = clock(span.start), clock(span.end)
    return f"gap {start}-{end} ({span.minutes} min)"


def check_inside(worked: Iterable[Span], hours: Span):
    for span in worked:
        if span.start < hours.start or span.end > hours.end:
            raise ValueError(f"outside opening hours: {span}")


def find_gaps(worked: Iterable[Span], hours: Span) -> List[str]:
    """One label per uncovered stretch of the opening hours."""
    worked = list(worked)
    check_inside(worked, hours)
    merged = merge_spans(worked)
    lefts = [hours.start] + [span.end for span in merged]
    rights = [span.start for span in merged] + [hours.end]
    return [
        gap_label(Span(left, right))
        for left, right in zip(lefts, rights)
        if left < right
    ]

