# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(8 * 60, 18 * 60)


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [Span(480, 720), Span(780, 1080)]
        self.assertEqual(
            find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        worked = [Span(540, 700), Span(600, 900)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 08:00-09:00 (60 min)", "gap 15:00-18:00 (180 min)"]
        )

    def test_nothing_worked(self):
        self.assertEqual(
            find_gaps([], OPEN), ["gap 08:00-18:00 (600 min)"]
        )

    def test_full_coverage(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])

    def test_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(420, 600)], OPEN)


if __name__ == "__main__":
    unittest.main()
